(()=>{'use strict';const dataNode=document.getElementById('postcard-data');if(!dataNode)return;const rows=JSON.parse(dataNode.textContent),$=x=>document.getElementById(x);let index=0;const select=$('card-select');function scale(){const w=Number($('card-zoom').value);$('card-image').style.width=w+'%';$('card-zoom-value').textContent=w+'%'}function show(i,hash=true){index=i;const r=rows[i];select.value=String(i);$('card-image').src=r.preview;$('card-image').alt=r.caption||'Cartolina '+(i+1);$('card-full').href=r.image;$('card-old').href=r.uncropped||r.old;$('card-title').textContent=r.caption||'Cartolina '+(i+1);$('card-text').textContent=r.text||'[Trascrizione non ancora disponibile.]';$('card-status').textContent=r.status;$('card-note').textContent=r.note||'';$('card-count').textContent=(i+1)+' di '+rows.length;$('card-prev').disabled=i===0;$('card-next').disabled=i===rows.length-1;$('card-zoom').value='100';scale();$('card-frame').scrollTop=0;$('card-frame').scrollLeft=0;if(hash)history.replaceState(null,'','#cartolina-'+(i+1))}select.addEventListener('change',()=>show(Number(select.value)));$('card-prev').addEventListener('click',()=>show(Math.max(0,index-1)));$('card-next').addEventListener('click',()=>show(Math.min(rows.length-1,index+1)));$('card-zoom').addEventListener('input',()=>{$('card-image').src=rows[index].image;scale()});$('card-fit').addEventListener('click',()=>{$('card-zoom').value='100';scale()});document.querySelectorAll('[data-card-index]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show(Number(a.dataset.cardIndex));$('lettore-cartoline').scrollIntoView({behavior:'smooth'})}));const h=location.hash.match(/^#cartolina-(\d+)$/);show(h?Math.max(0,Math.min(rows.length-1,Number(h[1])-1)):0,false);})();
